(()=>{
'use strict';const D=window.ECON,G=window.DIAGRAMS,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let subject='macro';const scoped=()=>D.chapters.filter(x=>x.subject===subject),subjectQuestions=()=>D.questions.filter(q=>scoped().some(c=>c.id===q.chapter));let c=D.chapters[0],mode='notes',filter='all',qtype='all',search='',bankPage=0,sprint=null,card=0;const names={notes:'Chapter notes',visual:'Exam diagrams',bank:'Question bank',recall:'Recall cards'};let progress={answered:{},known:[]};try{const p=JSON.parse(localStorage.getItem('econ-revision-v1'));if(p&&p.answered&&Array.isArray(p.known))progress=p}catch{}const save=()=>{try{localStorage.setItem('econ-revision-v1',JSON.stringify(progress))}catch{}score()};function score(){$('#score').textContent=Object.values(progress.answered).filter(Boolean).length}
const terms=['National income','Domestic income','Factor incomes','Transfer incomes','Normal residents','Domestic territory','Net factor income from abroad','Depreciation','Net indirect taxes','Value added','Double counting','Compensation of employees','Operating surplus','Mixed income','Revenue receipts','Capital receipts','Revenue expenditure','Capital expenditure','Fiscal deficit','Primary deficit','Revenue deficit','Aggregate demand','Aggregate supply','Autonomous consumption','Induced consumption','Average propensity to consume','Marginal propensity to consume','Average propensity to save','Marginal propensity to save','Full employment','Deficient demand','Excess demand','Inflationary gap','Deflationary gap','Autonomous transactions','Accommodating transactions'];function rich(s){let t=esc(s).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');terms.forEach(term=>{t=t.replace(new RegExp('\\b'+term+'\\b','gi'),m=>'<strong>'+m+'</strong>')});return t}
function paras(s){return s.split(/\n\n/).map(x=>'<p>'+rich(x)+'</p>').join('')}
function studyBlock(title,text,tone='point'){return `<section class="study-block ${tone}">${title?`<h4>${rich(title)}</h4>`:''}<p>${rich(text)}</p></section>`}
function lessonBody(l){return lessonContent(l)+(l.comparison?comparison(l.comparison):'')}
function comparison(t){return `<div class="comparison-wrap"><table class="study-comparison"><thead><tr>${t.heads.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${t.rows.map(r=>`<tr>${r.map((v,i)=>i===0?`<th scope="row">${esc(v)}</th>`:`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function lessonContent(l){
 if(l.blocks)return `<div class="study-grid">${l.blocks.map(b=>studyBlock(b.title,b.text,b.tone)).join('')}</div>`;
 if(l.points)return `<div class="study-grid">${l.points.map(p=>{let at=p.indexOf(':');return studyBlock(at>0?p.slice(0,at):'',at>0?p.slice(at+1).trim():p)}).join('')}</div>${studyBlock('Remember',l.takeaway,'insight')}`;
 let out=[],tiles=[];const flush=()=>{if(tiles.length){out.push(`<div class="study-grid">${tiles.join('')}</div>`);tiles=[]}};
 l.body.split(/\n\n/).forEach((p,i)=>{
  const pieces=p.split(/(?=\*\*[^*]{2,100}:\*\*)/).filter(Boolean);
  pieces.forEach(part=>{let m=part.match(/^\*\*([^*]+):\*\*\s*([\s\S]*)$/);
   if(m){let tone=/concern|weakness|cost|limitation|challenge|neglect|unemployment|slowdown|problem|low |inadequate|deficient|bias|drain/i.test(m[1])?'caution':'point';tiles.push(studyBlock(m[1],m[2],tone))}
   else{flush();let tone=i===0&&!l.key?'definition':/example|case illustrates|for example/i.test(part)?'example':/do not confuse|do not treat|keep.*distinct|distinguish.*from|not automatically/i.test(part)?'insight':'prose';out.push(studyBlock('',part,tone))}
  });
 });flush();return `<div class="lesson-body">${out.join('')}</div>`
}
function chapterFlow(){return c.flow?`<section class="chapter-map"><div class="section-top"><h2>At a glance</h2><span>The chapter’s big picture</span></div><div class="chapter-flow">${c.flow.map((x,i)=>`<div class="flow-step"><div class="flow-top"><span>${String(i+1).padStart(2,'0')}</span><i></i></div><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p></div>`).join('')}</div></section>`:''}

function head(title,sub,eye){return `<div class="eyebrow">${eye||(subject==='macro'?'Macroeconomics':'Indian Economic Development')+' · Class XII'}</div><h1>${esc(title)}</h1>${sub?`<p class="intro">${esc(sub)}</p>`:''}`}
function outline(){return c.lessons.map(l=>l.textbookHeading||l.title).filter((h,i,all)=>all.indexOf(h)===i)}
function originalHeading(l){return l.textbookHeading||''}
function notes(){let o=outline();return head(c.title,'Understand the idea, remember the key points, then practise explaining it in your own words.','Chapter '+c.number+' · '+c.lessons.length+' concepts')+`<div class="toolbar"><button data-go="bank">Practise this chapter</button></div>${chapterFlow()}<details class="card"><summary>Chapter outline</summary>${o.length?o.map(h=>`<a href="#lesson-${c.lessons.findIndex(l=>(l.textbookHeading||l.title)===h)}">${esc(h)}</a>`).join(''):''}</details>`+c.lessons.map((l,i)=>`<article class="card lesson-card ${/box|zone|case/i.test(l.kind)?'extension-card':''}" id="lesson-${i}"><div class="label">${esc(l.kind)} · ${String(i+1).padStart(2,'0')}</div>${originalHeading(l)?`<div class="tb-heading">${esc(originalHeading(l))}</div>`:''}<h3>${esc(l.title)}</h3>${lessonBody(l)}${l.formula?`<div class="formula">${esc(l.formula).replace(/\n/g,'<br>')}</div>`:''}${diagramFor(c.id,i)}<div class="toolbar"><button data-recall="${i}">Recall this concept</button></div></article>`).join('')}
function diagramFor(n,i){const map={'2-5':['circular'],'7-1':['consumption'],'7-3':['saving'],'8-0':['ad','si'],'9-1':['deflation'],'9-2':['inflation'],'11-2':['fx-demand-up']};let ids=map[n+'-'+i]||[];if(n==='3'&&i===3)return `<figure>${G.bridge()}<figcaption class="note">Apply each bridge once. Reverse its sign when moving backwards.</figcaption></figure>`;return ids.map(id=>{let e=window.EXAM_DIAGRAMS.find(x=>x.id===id);return `<figure class="note-diagram">${e.draw()}<figcaption class="note">${esc(e.explain)}</figcaption><button data-exam="${id}">Practise drawing · steps & labels →</button></figure>`}).join('')}
function answerMarkup(q){if(q.tag==='Full-topic review')return lessonBody({body:q.solution.split('\n').slice(1).join('\n\n'),key:q.id});if(q.type==='mcq')return `<strong>${esc(q.options[q.answer])}</strong><p>${rich(q.explanation)}</p>`;let lines=q.solution.split('\n');return lines.map((s,i)=>i===0&&q.type==='theory'?`<h3>${esc(s)}</h3>`:`<p>${rich(s)}</p>`).join('')}
function question(q){let old=progress.answered[q.id];return `<article class="card question" id="${q.id}"><div class="q-meta"><span>${q.chapter.startsWith('i')?'IED':'MACRO'} · CH ${q.chapter.replace('i','')}</span><span>${q.marks} ${q.marks===1?'MARK':'MARKS'}</span><span>${esc(q.tag)}</span>${old===true?'<span>✓ Previously correct</span>':''}</div><h3>${esc(q.q)}</h3>${q.type==='mcq'?q.options.map((o,i)=>`<button class="option" data-answer="${i}" data-q="${q.id}"><span class="option-letter">${'ABCD'[i]}</span>${esc(o)}</button>`).join(''):`<label class="note" for="draft-${q.id}">Try your answer first (optional)</label><textarea class="draft" id="draft-${q.id}" placeholder="Write your points or working…"></textarea><button class="action" data-reveal="${q.id}" aria-expanded="false">Show worked answer</button>`}<div class="answer" id="answer-${q.id}" hidden aria-live="polite"></div></article>`}
function bank(){let qs=subjectQuestions().filter(q=>(filter==='all'||q.chapter===filter)&&(qtype==='all'||q.type===qtype)&&(!search||(q.q+' '+(q.solution||'')+' '+q.tag).toLowerCase().includes(search.toLowerCase())));if(sprint)return sprintView();return head('Question bank',`${subjectQuestions().filter(q=>q.type==='mcq').length} MCQs, ${subjectQuestions().filter(q=>q.type==='numerical').length} numericals and ${subjectQuestions().filter(q=>q.type==='theory').length} theory/application questions. Original practice based on official CBSE formats, with checking and worked answers.`)+`<div class="toolbar"><select id="filter" aria-label="Question chapter"><option value="all">All chapters</option>${scoped().map(x=>`<option value="${x.id}" ${filter===x.id?'selected':''}>${x.number}. ${esc(x.title)}</option>`).join('')}</select><select id="type" aria-label="Question type">${[['all','All question types'],['mcq','MCQs · instant checking'],['numerical','Numericals · worked answers'],['theory','Theory · answer points']].map(([v,t])=>`<option value="${v}" ${qtype===v?'selected':''}>${t}</option>`).join('')}</select><input id="q-search" aria-label="Search questions" placeholder="Search a topic…" value="${esc(search)}"><button id="q-search-btn">Search</button></div><div class="note">${qs.length} questions · For theory: give distinct points, explain why, and apply them to the question. Marks shown are practice targets.</div>`+(qs.length?qs.slice(bankPage*20,(bankPage+1)*20).map(question).join('')+`<div class="toolbar bank-pages"><button id="bank-prev" ${bankPage===0?'disabled':''}>← Previous set</button><span class="note">Set ${bankPage+1} of ${Math.ceil(qs.length/20)}</span><button id="bank-next" ${(bankPage+1)*20>=qs.length?'disabled':''}>Next set →</button></div>`:'<article class="card">No questions match these filters.</article>')}
function sprintView(){if(sprint.index>=sprint.qs.length)return head('Sprint complete',`You scored ${sprint.correct} out of ${sprint.qs.length}. Review any uncertain concepts, then try a fresh set.`)+`<div class="toolbar"><button id="new-sprint">Another sprint</button><button id="end-sprint">Back to question bank</button></div>`;let q=sprint.qs[sprint.index];return head('10-question sprint',`Question ${sprint.index+1} of ${sprint.qs.length} · ${sprint.correct} correct so far`)+question(q)+`<div class="toolbar"><button id="next-sprint" disabled>Next question →</button><button id="end-sprint">End sprint</button></div>`}
function recall(){let l=c.lessons[card%c.lessons.length],id=c.id+'-'+(l.key||card);return head('Recall the concept','Say the answer before revealing it. Use the textbook headings and include the key relationship or example.','Chapter '+c.number+' · Card '+(card+1)+' of '+c.lessons.length)+`<article class="card"><div class="label">${esc(l.kind)}</div><h2>${esc(l.title)}</h2><p>What are the definition, key points and common exam traps?</p><button id="flip" class="action primary" aria-expanded="false">Reveal answer</button><div id="recall-answer" hidden class="answer">${lessonBody(l)}${l.formula?`<div class="formula">${esc(l.formula).replace(/\n/g,'<br>')}</div>`:''}</div></article><div class="toolbar"><button id="prev-card">← Previous</button><button id="know-card">${progress.known.includes(id)?'✓ Marked known':'Mark as known'}</button><button id="next-card">Next →</button></div><p class="note">${progress.known.length} of ${D.chapters.reduce((s,x)=>s+x.lessons.length,0)} concepts marked known in this browser.</p>`}
const labNames={functions:'Consumption & saving',equilibrium:'AD–AS and S–I',multiplier:'Multiplier rounds',credit:'Credit creation',gap:'Demand gaps',forex:'Foreign exchange'};let lab='functions',visualMode='exam',examId='consumption';
function slider(id,label,min,max,value,step=1){return `<label>${label}: <output id="${id}-v">${value}</output><input id="${id}" type="range" min="${min}" max="${max}" value="${value}" step="${step}"></label>`}
function examView(){const e=window.EXAM_DIAGRAMS.find(x=>x.id===examId)||window.EXAM_DIAGRAMS[0];return head('Diagrams to draw in the exam','Study the model drawing, reproduce it from memory, then check the axes, labels, intercepts and explanation. The fixed drawings use standard textbook conventions.')+`<div class="toolbar lab-nav"><button class="active" data-visual-mode="exam">Exam drawings</button><button data-visual-mode="lab">Interactive concept lab</button></div><div class="toolbar"><select id="exam-picker" class="diagram-picker" aria-label="Choose an exam diagram">${window.EXAM_DIAGRAMS.map(x=>`<option value="${x.id}" ${x.id===e.id?'selected':''}>Ch ${x.chapter} · ${esc(x.title)}</option>`).join('')}</select><button id="draw-test">Hide model · try drawing</button></div><article class="card exam-draw"><div class="label">Chapter ${e.chapter} · Draw and explain</div><h2>${esc(e.title)}</h2><div class="exam-grid"><div class="exam-stage" id="exam-model">${e.draw()}</div><div><h3>How to draw it</h3><ol>${e.steps.map(s=>`<li>${rich(s)}</li>`).join('')}</ol><h3>What to write below it</h3><p class="exam-explain">${rich(e.explain)}</p></div></div><div class="trap"><strong>Common mistake:</strong> ${esc(e.trap)}</div></article>`}
function visual(){if(visualMode==='exam')return examView();let controls='';if(['functions','equilibrium','gap'].includes(lab))controls=slider('a','Autonomous consumption',20,200,80,10)+slider('b','MPC',.1,.9,.75,.05)+(lab!=='functions'?slider('I','Autonomous investment',20,300,100,10):'')+(lab==='gap'?slider('yf','Full-employment income',400,1600,1000,100):'');if(lab==='multiplier')controls=slider('b','MPC',0,.9,.8,.05)+slider('injection','Investment increase',20,200,100,10);if(lab==='credit')controls=slider('reserve','Reserve ratio (%)',5,50,20,5)+slider('deposit','Initial deposit',500,5000,1000,500);if(lab==='forex')controls=`<label>Shift which curve?<select id="fx-kind"><option value="demand">Dollar demand</option><option value="supply">Dollar supply</option></select></label>`+slider('shift','Rightward shift',0,40,20,5);return head('Interactive concept lab','Change one assumption and watch the mechanism. Use Exam drawings for the fixed diagrams to practise reproducing.')+`<div class="toolbar lab-nav"><button data-visual-mode="exam">Exam drawings</button><button class="active" data-visual-mode="lab">Interactive concept lab</button></div><div class="toolbar">${Object.entries(labNames).map(([k,v])=>`<button data-lab="${k}" class="${lab===k?'active':''}">${v}</button>`).join('')}</div><article class="card"><h3>${labNames[lab]}</h3><div class="sliders">${controls}</div><div id="lab-result" aria-live="polite"></div></article>`}
function labUpdate(){const v=id=>Number($('#'+id)?.value),a=v('a'),b=v('b'),I=v('I');document.querySelectorAll('.sliders input').forEach(el=>$('#'+el.id+'-v').textContent=el.value);let t='';if(lab==='functions')t=G.consumption(a,b)+G.saving(a,b)+`<div class="result">Break-even income = ${(a/(1-b)).toFixed(2)} · MPS = ${(1-b).toFixed(2)}</div><p>Below break-even, C &gt; Y and saving is negative. At break-even, APC = 1 and APS = 0. MPC is the slope of C; MPS is the slope of S.</p>`;if(lab==='equilibrium')t=G.demand(a,b,I)+G.si(a,b,I)+`<div class="result">Y* = (C̄ + I)/(1 − MPC) = ${((a+I)/(1-b)).toFixed(2)}</div><p>At this income, planned S = I = ${I}. Below it, AD exceeds output and inventories fall; above it, inventories accumulate. The model assumes spare capacity and constant prices.</p>`;if(lab==='gap'){let yf=v('yf'),ad=a+b*yf+I,g=ad-yf,eq=(a+I)/(1-b);t=G.demand(a,b,I,yf,true)+`<div class="result">${Math.abs(g)<.001?'No demand gap':g>0?'Inflationary gap':'Deflationary gap'}: ${Math.abs(g).toFixed(2)}</div><p>At full-employment income ${yf}, AD = ${ad.toFixed(2)}. Notional equilibrium is ${eq.toFixed(2)}. ${g>0?'Reduce':'Raise'} autonomous expenditure by ${Math.abs(g).toFixed(2)} to close the gap. Beyond capacity, the notional output calculation signals inflationary pressure.</p>`}if(lab==='multiplier'){let z=v('injection'),k=1/(1-b),rows=Array.from({length:8},(_,i)=>({round:i+1,income:z*b**i}));t=`<div class="result">k = ${k.toFixed(2)} · Final ΔY = ${(z*k).toFixed(2)}</div><p>Each round’s consumption becomes the next person’s income. These bars show the first eight rounds; the formula includes every subsequent round.</p><div class="rounds">${rows.map(r=>`<div class="round"><span>Round ${r.round}</span><div style="width:${Math.max(r.income/z*75,1)}%;background:var(--green);height:16px;border-radius:3px"></div><strong>${r.income.toFixed(2)}</strong></div>`).join('')}</div><p class="note">Assumptions: constant MPC, no additional tax/import leakages, stable prices and available capacity.</p>`}if(lab==='credit'){let r=v('reserve')/100,z=v('deposit'),total=z/r,rows=Array.from({length:5},(_,i)=>{let dep=z*(1-r)**i;return [i+1,dep,dep*r,dep*(1-r)]});t=`<div class="result">Total deposits = ${total.toFixed(2)} · Additional credit = ${(total-z).toFixed(2)}</div><table><caption>First five rounds of deposit creation</caption><thead><tr><th>Round</th><th>Deposit</th><th>Reserves</th><th>Loan</th></tr></thead><tbody>${rows.map(row=>'<tr>'+row.map(x=>'<td>'+Number(x).toFixed(2)+'</td>').join('')+'</tr>').join('')}</tbody></table><p>The maximum deposit multiplier is ${(1/r).toFixed(2)}. Total deposits include the initial deposit. Assume no cash leakage, no excess reserves and all loans redeposited.</p>`}if(lab==='forex'){let kind=$('#fx-kind').value,z=v('shift'),e=(180+(kind==='demand'?z:-z))/3;t=G.forex(z,kind)+`<div class="result">New rate: ₹${e.toFixed(2)}/$ · ${z===0?'Original equilibrium':kind==='demand'?'Rupee depreciation':'Rupee appreciation'}</div><p>${kind==='demand'?'More imports or overseas investment can increase dollar demand; the ₹/$ rate rises.':'More exports or inward investment can increase dollar supply; the ₹/$ rate falls.'} Original rate is ₹60/$. This is a curve shift, not a movement caused by the exchange rate itself.</p>`}$('#lab-result').innerHTML=t}
function render(){ $('#crumb').textContent=names[mode];$('#modes').innerHTML=Object.entries(names).filter(([k])=>subject==='macro'||k!=='visual').map(([k,v])=>`<button class="nav-item ${mode===k?'active':''}" data-mode="${k}" ${mode===k?'aria-current="page"':''}><span class="nav-dot"></span>${v}${k==='bank'?'<span class="nav-count">'+subjectQuestions().length+'</span>':''}</button>`).join('');$('#subjects').innerHTML=[['macro','Macro'],['ied','IED']].map(([id,label])=>`<button data-subject="${id}" class="${subject===id?'active':''}" aria-pressed="${subject===id}">${label}</button>`).join('');$('#chapters').innerHTML=scoped().map(x=>`<button class="chapter-link ${x.id===c.id?'active':''}" data-chapter="${x.id}"><span class="chapter-no">${String(x.number).padStart(2,'0')}</span><span>${esc(x.title)}</span></button>`).join('');$('#view').innerHTML=({notes,visual,bank,recall}[mode])();score();if(mode==='visual'&&visualMode==='lab'){labUpdate();document.querySelectorAll('.sliders input,.sliders select').forEach(x=>x.addEventListener('input',labUpdate))} }
function change(m){mode=m;search='';bankPage=0;sprint=null;render();window.scrollTo(0,0);$('#rail').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')}
function startSprint(){let pool=subjectQuestions().filter(q=>q.type==='mcq'&&(filter==='all'||q.chapter===filter));for(let i=pool.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}sprint={qs:pool.slice(0,10),index:0,correct:0};mode='bank';render();window.scrollTo(0,0)}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.subject){subject=b.dataset.subject;c=scoped()[0];filter='all';qtype='all';card=0;change('notes')}else if(b.dataset.exam){examId=b.dataset.exam;visualMode='exam';change('visual')}else if(b.dataset.chapter){c=D.chapters.find(x=>x.id===b.dataset.chapter);card=0;change('notes')}else if(b.dataset.mode)change(b.dataset.mode);else if(b.dataset.go==='bank'){filter=c.id;change('bank')}else if(b.dataset.recall!==undefined){card=Number(b.dataset.recall);change('recall')}else if(b.dataset.answer!==undefined){let q=D.questions.find(x=>x.id===b.dataset.q),isCorrect=Number(b.dataset.answer)===q.answer;document.querySelectorAll(`#${q.id} .option`).forEach((x,i)=>{x.disabled=true;if(i===q.answer)x.classList.add('correct');else if(x===b)x.classList.add('wrong')});let ans=$('#answer-'+q.id);ans.hidden=false;ans.innerHTML=`<strong>${isCorrect?'Correct.':'Review this one.'}</strong> `+answerMarkup(q);progress.answered[q.id]=isCorrect;save();if(sprint){if(isCorrect)sprint.correct++;$('#next-sprint').disabled=false}}else if(b.dataset.reveal){let q=D.questions.find(x=>x.id===b.dataset.reveal),ans=$('#answer-'+q.id);ans.hidden=!ans.hidden;ans.innerHTML=answerMarkup(q);b.textContent=ans.hidden?'Show worked answer':'Hide answer';b.setAttribute('aria-expanded',String(!ans.hidden))}else if(b.dataset.visualMode){visualMode=b.dataset.visualMode;render()}else if(b.id==='draw-test'){let el=$('#exam-model');el.hidden=!el.hidden;b.textContent=el.hidden?'Show model drawing':'Hide model · try drawing'}else if(b.dataset.lab){lab=b.dataset.lab;render()}else if(b.id==='sprint'||b.id==='new-sprint')startSprint();else if(b.id==='next-sprint'){sprint.index++;render();window.scrollTo(0,0)}else if(b.id==='end-sprint'){sprint=null;render()}else if(b.id==='menu'){let open=$('#rail').classList.toggle('open');b.setAttribute('aria-expanded',String(open))}else if(b.id==='bank-next'||b.id==='bank-prev'){bankPage+=b.id==='bank-next'?1:-1;render();window.scrollTo(0,0)}else if(b.id==='q-search-btn'){bankPage=0;search=$('#q-search').value;render()}else if(b.id==='flip'){let el=$('#recall-answer');el.hidden=!el.hidden;b.textContent=el.hidden?'Reveal answer':'Hide answer';b.setAttribute('aria-expanded',String(!el.hidden))}else if(b.id==='next-card'||b.id==='prev-card'){card=(card+(b.id==='next-card'?1:-1)+c.lessons.length)%c.lessons.length;render()}else if(b.id==='know-card'){let id=c.id+'-'+(c.lessons[card].key||card);if(!progress.known.includes(id))progress.known.push(id);save();render()}});
document.addEventListener('change',e=>{if(e.target.id==='exam-picker'){examId=e.target.value;render()}if(e.target.id==='filter'){bankPage=0;filter=e.target.value;render()}if(e.target.id==='type'){bankPage=0;qtype=e.target.value;render()}});document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='q-search'){$('#q-search-btn').click()}if(e.key==='Escape'){$('#rail').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')}});
render();
})();
